package library.flow; public class Dinic { static class E{int to,rev,cap;E(int t,int r,int c){to=t;rev=r;cap=c;}} private E[][] g;private int[] level,it; public Dinic(int n){g=new E[n][];for(int i=0;i<n;i++)g[i]=new E[0];} private void addArr(int u,E e){E[] a=g[u],b=new E[a.length+1];System.arraycopy(a,0,b,0,a.length);b[a.length]=e;g[u]=b;} public void addEdge(int u,int v,int c){E a=new E(v,g[v].length,c),b=new E(u,g[u].length,0);addArr(u,a);addArr(v,b);a.rev=g[v].length-1;b.rev=g[u].length-1;} private boolean bfs(int s,int t){level=new int[g.length];for(int i=0;i<level.length;i++)level[i]=-1;int[] q=new int[g.length];int h=0,r=0;q[r++]=s;level[s]=0;while(h<r){int u=q[h++];for(E e:g[u])if(e.cap>0&&level[e.to]<0){level[e.to]=level[u]+1;q[r++]=e.to;}}return level[t]>=0;} private int dfs(int u,int t,int f){if(u==t)return f;for(;it[u]<g[u].length;it[u]++){E e=g[u][it[u]];if(e.cap>0&&level[e.to]==level[u]+1){int x=dfs(e.to,t,Math.min(f,e.cap));if(x>0){e.cap-=x;g[e.to][e.rev].cap+=x;return x;}}}return 0;} public int maxFlow(int s,int t){int flow=0,x;while(bfs(s,t)){it=new int[g.length];while((x=dfs(s,t,Integer.MAX_VALUE))>0)flow+=x;}return flow;} }
